<script setup lang="ts">
interface N8nNode { id: string | null; name: string; type: string }
interface N8nWorkflow { id: string | null; name: string; active: boolean; updatedAt: string | null; nodes: N8nNode[]; connections: unknown[] }
interface N8nResponse { available: boolean; message?: string; workflows: N8nWorkflow[] }
const { data, error, refresh } = await useFetch<N8nResponse>('/api/n8n')
</script>
<template><main class="space-y-5"><div class="flex justify-between gap-3"><div><p class="text-xs font-bold uppercase tracking-widest text-fg-muted">Optional adapter</p><h1 class="mt-2 text-3xl font-black">n8n inspection</h1><p class="mt-1 text-sm text-fg-muted">Read-only normalized workflow snapshots. The control plane remains authoritative.</p></div><button class="rounded-control border border-[var(--bs-border)] px-3 py-2 text-sm font-bold" @click="refresh()">Refresh</button></div><p v-if="error" class="text-danger">{{ error.message }}</p><p v-if="!data?.available" class="rounded-card border border-warning/40 bg-[var(--bs-status-warning-bg)] p-4">{{ data?.message }}</p><article v-for="workflow in data?.workflows || []" :key="workflow.id || workflow.name" class="rounded-card border border-[var(--bs-border)] bg-surface p-5"><div class="flex justify-between"><h2 class="font-black">{{ workflow.name }}</h2><DashboardStatusPill :value="workflow.active ? 'published' : 'inactive'" /></div><p class="mt-1 text-xs text-fg-muted">{{ workflow.nodes.length }} nodes · {{ workflow.connections.length }} connections · {{ workflow.updatedAt || 'unknown sync time' }}</p><div class="mt-4 space-y-2"><div v-for="node in workflow.nodes" :key="node.id || node.name" class="rounded-control border border-[var(--bs-border)] p-3 text-sm"><strong>{{ node.name }}</strong><span class="ms-2 font-mono text-xs text-fg-muted">{{ node.type }}</span></div></div></article></main></template>
